import { prepareGenerationGuidance } from './generationGuidance';
import { prepareProfileRequest } from './profiles/profileContext';
import { VariantHistoryService } from './VariantHistoryService';
import type { AgentVariantsOrchestrator } from '../agent-variants';
import { createAgentVariantsOrchestrator } from './createAgentVariantsOrchestrator';
import { SessionBridgeService } from './SessionBridgeService';
import type { TelemetryService } from './TelemetryService';
import { VariantRunService } from './VariantRunService';
import {
  WorkerExecutorService,
  isWorkerExecutorEnabled,
} from '../agent-variants/WorkerExecutorService';
import { getConfigManager } from './ConfigManager';

export type VariantsRuntime = {
  history: VariantHistoryService;
  bridge: SessionBridgeService;
  orchestrator: AgentVariantsOrchestrator;
  runService: VariantRunService;
};

export type CreateVariantsRuntimeOptions = {
  history?: VariantHistoryService;
  onGeneratedProject?: (projectPath: string) => Promise<void>;
  projectPath: string;
  staticEntry: string | undefined;
  telemetry?: TelemetryService;
  devServerContext?: Parameters<SessionBridgeService['setDevServerContext']>[0];
  devServerHealth?: Parameters<
    SessionBridgeService['updateDevServerHealth']
  >[0];
};

export const createVariantsRuntime = (
  options: CreateVariantsRuntimeOptions,
): VariantsRuntime => {
  const history = options.history ?? new VariantHistoryService();
  const bridge = new SessionBridgeService();
  bridge.startSession(options.projectPath);
  if (options.devServerContext) {
    bridge.setDevServerContext(options.devServerContext);
  }
  if (options.devServerHealth) {
    bridge.updateDevServerHealth(options.devServerHealth);
  }

  const orchestrator = createAgentVariantsOrchestrator({
    history,
    bridge,
    telemetry: options.telemetry,
    projectPathFallback: options.projectPath,
    staticEntry: options.staticEntry,
  });
  const executor = isWorkerExecutorEnabled()
    ? new WorkerExecutorService({
        orchestrator,
        telemetry: options.telemetry,
        configuredWorkerVendor: () =>
          getConfigManager().getConfiguredWorkerVendor(),
        workerVendorFallbackEnabled: () =>
          getConfigManager().isWorkerVendorFallbackEnabled(),
        configuredWorkerModelFor: (vendor) =>
          getConfigManager().getConfiguredWorkerModel(vendor),
        configuredRunnerPaths: () =>
          getConfigManager().getConfiguredRunnerPaths(),
      })
    : undefined;
  const runService = new VariantRunService({
    history,
    prepareGuidance: (request) =>
      prepareGenerationGuidance(request, options.telemetry),
    prepareProfile: prepareProfileRequest,
    storage: history.store.storage,
    onGeneratedProject: options.onGeneratedProject,
    bridge,
    orchestrator,
    projectPath: options.projectPath,
    staticEntry: options.staticEntry,
    ...(executor ? { executor } : {}),
  });

  return { bridge, orchestrator, runService, history };
};
